-- Hand-maintained (NOT generated): Central Shroud (zone 150) monsters placed from retail 1.23b
-- packet captures. Apply after seed_bnpc_01..07; re-apply after re-applying 05.
-- Idempotent: deletes its own ID range first (pools/groups/bnpcIds 2100001-2100999).
--
-- Positions, rotations and model classes: first placement of each actor in the xivl-captures
-- spawn_observations (s2c 0x00CA/0x00CC/0x00CE; captures gridania_to_coerthas, gather_wood,
-- local_leve_complete = fst0Fld01, and party_battle_leve = fst0Fld01a, the leve copy of the same
-- field, placed here in 150 where players are) [CAP].
-- capture-cited rows (migrations 20260918_000044 / 20260717_000006) where their row sits on the
-- same point with the same class [CAP]; otherwise noted per row. Their rows whose
-- point is not in spawn_observations (three Giant Bats, a Lv31 opo-opo, the Lv31 toadtrap, a
-- glowfly, eleven chigoe/funguar points) are left out. HP/MP come from battle/stats.lua at spawn
-- (fit to the same captures), so groups keep hp = mp = 0.
--
-- Replaces, not duplicates: generator rows (bnpcId 1000001-1999999) in zone 150 of the same model
-- class within 12 units of a captured point are deleted (they are the same points, rounded to 10
-- units through the bestiary, often with a guessed variant or level). Pools copy combat, skill,
-- spell and mod columns from the named generator pool of the same monster; groups copy its drop
-- list and respawn time.

DELETE FROM `server_battlenpc_spawn_locations` WHERE `bnpcId` BETWEEN 2100001 AND 2100999;
DELETE FROM `server_battlenpc_groups` WHERE `groupId` BETWEEN 2100001 AND 2100999;
DELETE FROM `server_battlenpc_pool_mods` WHERE `poolId` BETWEEN 2100001 AND 2100999;
DELETE FROM `server_battlenpc_pools` WHERE `poolId` BETWEEN 2100001 AND 2100999;

-- Variants with no classPath in gamedata_actor_class: the capture binds them as these classes (0x00CC).
UPDATE `gamedata_actor_class` SET `classPath`='/Chara/Npc/Monster/Petitghost/PetitghostLesserStandard', `propertyFlags`=IF(`propertyFlags`=0,23,`propertyFlags`), `eventConditions`=IFNULL(`eventConditions`,'{\n  "talkEventConditions": [],\n  "noticeEventConditions": [\n    {\n      "unknown1": 0,\n      "unknown2": 1,\n      "conditionName": "noticeEvent"\n    }\n  ],\n  "emoteEventConditions": [],\n  "pushWithCircleEventConditions": []\n}') WHERE `id`=2104324 AND `classPath`='';
UPDATE `gamedata_actor_class` SET `classPath`='/Chara/Npc/Monster/Funguar/FunguarLesserStandard', `propertyFlags`=IF(`propertyFlags`=0,23,`propertyFlags`), `eventConditions`=IFNULL(`eventConditions`,'{\n  "talkEventConditions": [],\n  "noticeEventConditions": [\n    {\n      "unknown1": 0,\n      "unknown2": 1,\n      "conditionName": "noticeEvent"\n    }\n  ],\n  "emoteEventConditions": [],\n  "pushWithCircleEventConditions": []\n}') WHERE `id`=2105917 AND `classPath`='';

