-- Retire the rounded generator copies of these points (same model class, within 12 units).
DROP TEMPORARY TABLE IF EXISTS `tmp_cap150`;
CREATE TEMPORARY TABLE `tmp_cap150` (`x` FLOAT NOT NULL, `z` FLOAT NOT NULL, `cls` VARCHAR(64) NOT NULL);
DELETE s FROM `server_battlenpc_spawn_locations` s
  JOIN `server_battlenpc_groups` g ON g.`groupId`=s.`groupId`
  JOIN `server_battlenpc_pools` p ON p.`poolId`=g.`poolId`
  JOIN `gamedata_actor_class` a ON a.`id`=p.`actorClassId`
  JOIN `tmp_cap150` c ON BINARY c.`cls`=BINARY SUBSTRING_INDEX(a.`classPath`,'/',-1)
   AND (s.`positionX`-c.`x`)*(s.`positionX`-c.`x`)+(s.`positionZ`-c.`z`)*(s.`positionZ`-c.`z`) < 144
WHERE g.`zoneId`=150 AND s.`bnpcId` BETWEEN 1000001 AND 1999999;
DROP TEMPORARY TABLE `tmp_cap150`;

